import json

with open('/workspaces/semio/elements/ui/index.tsx') as f:
    lines = f.readlines()

# Extract EN translation JSON
json_start_line = None
for i, l in enumerate(lines):
    if 'en: {' in l and i > 4900:
        for j in range(i+1, i+5):
            if 'JSON.parse' in lines[j]:
                json_start_line = j
                break
        break

json_lines = []
collecting = False
for i in range(json_start_line, len(lines)):
    l = lines[i]
    if not collecting:
        idx = l.find('{')
        if idx >= 0:
            json_lines.append(l[idx:])
            collecting = True
    else:
        if '`' in l:
            end_idx = l.index('`')
            json_lines.append(l[:end_idx])
            break
        json_lines.append(l)

json_str = '\n'.join(json_lines)
data = json.loads(json_str)

# Check what's in design.panel now
panel = data['compose']['sketchpad']['app']['design']['panel']
print("Panel keys:", list(panel.keys()))
if 'workbench' in panel:
    print("SUCCESS: workbench found in panel!")
    print(json.dumps(panel['workbench'], indent=2))
else:
    # Search for workbench anywhere
    def find_key(obj, target, path=""):
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_path = f"{path}.{k}" if path else k
                if k == target:
                    print(f"Found {target} at: {new_path}")
                    return True
                find_key(v, target, new_path)
    find_key(data, "workbench")
